INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1030, 'ruRU', 'Я нашёл способ войти в Чертог Хаз''мула! Возьми Медальон Гни''кива из моего сундука. Победи трогга Ревелоша в чертоге перед комнатой карт и забери Стержень Цол. Соедини медальон и стержень в Посох Доисторической эпохи. Используй посох в комнате карт, чтобы открыть дверь в Чертог Хаз''мула. Сделай это, и чертог будет твоим! -Бейлог', 0),
(1050, 'ruRU', '<HTML>\n<BODY>\n<BR/>\n<BR/>\n<P>\nВ память о моём дорогом наставнике, Горацио М. Монтгомери, докторе медицины. Целитель, учитель, друг.\n</P>\n<BR/>\n<H1 align="center">\n50 BTFT - 25 ATFT\n</H1>\n<BR/>\n<P>\n"Мир полон больных и усталых. Наша работа, как целителей, НЕТ, как мужчин и женщин медицины — избавить их ВСЕХ от хвори."\n</P>\n<BR/>\n<P>\n- Г.М.М., доктор медицины, кандидат наук, доктор юридических наук, Гроссмейстер фермерства, выдающийся танцор, друг животных\n</P>\n<BR/>\n</BODY>\n</HTML>\n', 0),
(1090, 'ruRU', 'Похоже, что бы Клавен ни запер в этом сундуке, оно оказывает пагубное воздействие на обитателей башни. Подозреваю, что у других стражников могут быть похожие слабости, и, возможно, даже сам Клавен стал жертвой этих последствий. Агент Эмбер Кирнен ОВ:7, оперативник наземного уровня, R8', 0),
(1130, 'ruRU', 'Молот Зул''Фаррака Чтобы создать Молот Зул''Фаррака, сначала нужно отправиться к Алтарю Зула и получить священный молот у тролля-смотрителя. Затем нужно принести священный молот к алтарю на вершине троллиного города Джинта''алор. Использование священного молота у алтаря наполнит его силой и превратит в Молот Зул''Фаррака.', 0),
(1150, 'ruRU', 'SUPER CRITICAL TRIPLE-ENCODED DATA CARD 01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111', 0),
(1170, 'ruRU', 'Кургл, я с нетерпением жду твоего новейшего изобретения. Не могу дождаться, чтобы начать использовать его для документирования своих исследований. Пожалуйста, передай его моему посланнику. С наилучшими пожеланиями, Дарин Лайтвинд', 0),
(1190, 'ruRU', '<HTML>\n<BODY>\n<IMG src="Interface\\Pictures\\9330_Gammerita_sepia_256"/>\n</BODY>\n</HTML>', 0),
(1210, 'ruRU', 'Уровень секретности этих данных НАСТОЛЬКО высок, что ожидает изобретения нового числа, чтобы его описать!', 0),
(1270, 'ruRU', 'Нам больно упоминать, что мы в Snuff Inc получили сообщения о том, что некоторые жадные охотники за тубероидами мало заботятся о безопасности своих милых питомцев и отправляют их в тёмные, опасные закутки и щели в поисках тубероидов. Мы не одобряем такое безответственное поведение, но в целях удовлетворения клиентов мы включили гарантию с каждым проданным сурком, позволяющую новым владельцам вернуться в точку покупки и заменить потерянного питомца. Удачной охоты!', 0),
(1310, 'ruRU', 'Больше цитат!$B$B«Знаешь то чувство, когда заканчиваешь что-то создавать и впервые включаешь, чтобы испытать силу и радость изобретения, когда твоё устройство оживает? Гномы этого не знают».$B-- Никс Пружинспринг, Мастер-инженер гоблинов Газзатана$B$B«Инженерное дело — это умение превратить фантазию в нечто фантастическое!»$B-- Ровис МакКранкенспанк, изобретатель-гном', 0),
(1330, 'ruRU', 'Если какая-либо разумная жизнь найдёт эту записку, пусть спросит себя: «Какого чёрта они носятся вокруг с яростными тридцатиметровыми гигантами?» - Мук', 0),
(1370, 'ruRU', '01001101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01110100 01101111 00100000 01000011 01100001 01110011 01110100 01110000 01101001 01110000 01100101 00111010 00100000 01111001 01101111 01110101 01110010 00100000 01101100 01100001 01110101 01101110 01100100 01110010 01111001 00100111 01110011 00100000 01110010 01100101 01100001 01100100 01111001 00100000 01100110 01101111 01110010 00100000 01110000 01101001 01100011 01101011 01110101 01110000 00101110', 0),
(1391, 'ruRU', '<HTML>\n<BODY>\n<IMG src="Interface\\Pictures\\Linken_sepia_256px"/>\n</BODY>\n</HTML>', 0),
(1430, 'ruRU', 'Брат Нилс, мой виноград спасён! $N, податель этого манифеста, рискнул пройти через мой заражённый бандитами виноградник и собрал виноград, который я не смог. Хотя Доблески всё ещё бродят по ту сторону реки, почти весь мой урожай был спасён. Можешь добавить полную партию корзин винограда в свои запасы. Пусть Свет защитит нас, -Милли Осворт', 0),
(1470, 'ruRU', 'Пелвер Глубокоступ Тёмный Хранитель Пелвер — наш самый почитаемый ученик. Он нёс ключ дольше всех, и это дорого ему стоило. Когда его призовут для исполнения его бремени, он будет под охраной в Обители. Его жертва дорога нам, и он останется в наших сердцах на долгие годы... после того как тьма заберёт его.', 0),
(1490, 'ruRU', 'Соломон,$B$BПодатель этого указа получил официальный статус действующего помощника шерифа Штормграда. Вы можете обращаться к $g нему:ней', 0),
(1510, 'ruRU', '<HTML>\n<BODY>\n<H1 align="center">\nРУКОВОДСТВО ПОЛЬЗОВАТЕЛЯ КРИСТАЛЬНОГО ПИЛОНА\n</H1>\n<BR/>\n<P align="center">\n"Руководство по сбору и использованию энергетических кристаллов кратера Ун''Горо"\n</P>\n<BR/>\n<BR/>\n<P align="left">\nГлава 1: Северный пилон\n</P>\n<BR/>\n<P align="left">\nГлава 2: Восточный пилон\n</P>\n<BR/>\n<P align="left">\nГлава 3: Западный пилон\n</P>\n<BR/>\n</BODY>\n</HTML>\n', 0),
(1530, 'ruRU', '<HTML>\n<BODY>\n<H1 align="center">\nEASTERN PYLON TABLE DIAGRAM\n</H1>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_east"/>\n</BODY>\n</HTML>', 0),
(1550, 'ruRU', '<HTML>\n<BODY>\n<H1 align="center">\nWESTERN PYLON TABLE DIAGRAM\n</H1>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_west"/>\n</BODY>\n</HTML>', 0),
(1555, 'ruRU', 'Уравновешенный огненный клинок Гудстила - Наконец, хочу рассказать об одной из моих лучших кузнечных работ. Этот огненный клинок был невероятным мечом, который я подарил тому, кто, как мне казалось, был очень благородным и великим воином. Что ж, его одолел мурлок по имени Джаркваи? Что-то вроде этого. Это случилось, когда он путешествовал вдоль побережья Болота Печали и решил напасть на существо. Он проиграл и, видимо, бежал, но не раньше, чем оставил оружие этому мурлоку.', 0),
(1590, 'ruRU', 'Найди мне эти предметы и возвращайся в Газзатан со всеми ними, вместе с этой бухгалтерской книгой, и я тебя награжу.', 0),
(1610, 'ruRU', 'Эта наковальня — собственность Джордана Стилвелла - Пожалуйста, НЕ использовать! - Джордан', 0),
(1630, 'ruRU', '<Страницы покрыты древними эльфийскими рунами.> Эти страницы содержат воспоминания о событиях, произошедших при сборе и создании реагентов, необходимых для сотворения малых чар. Пусть наши враги никогда не получат доступ к этому либраму. Пусть я доживу до того дня, когда бледный свет луны снова озарит Кель''Талас. Пусть я умру лишь по милости Кель''таса. Пусть я убиваю во славу Иллидана. -Мастер Кариэль Винталус', 0),
(1690, 'ruRU', '<HTML>\n<BODY>\n<IMG src="Interface\\Pictures\\11733_ungoro_256"/>\n</BODY>\n</HTML>\n', 0),
(1710, 'ruRU', 'Привет, Фелнок! Мои исследования в Пылающих степях продвигаются великолепно. И я многим обязан $N за всю $gего:её; помощь! Вот что мне нужно для продолжения: Стальная спиральная бамперная кнутовина 17-калибровочный ледяной разводной ключ 12 фунтов утиных перьев Банка того клея, который ты делаешь Большое спасибо, Фелнок, и когда мы снова увидимся, напомни мне не насыпать уголь в твои сапоги! -Тинки', 0),
(1730, 'ruRU', 'Срочное сообщение Длиннорогу Скалоблюсту$b$bБольшой отряд кентавров из лагеря И''тока напал на один из наших караванов с припасами. Все члены караван погибли, как и все припасы. Это была смелая, беспрецедентная атака кентавров, и я боюсь, что их может быть больше.', 0),
(1750, 'ruRU', 'Здесь покоится король Теренас Менетил II -- Последний истинный король Лордерона. Велики были его деяния -- долгим было его правление -- немыслимой была его смерть.          «Пусть Отец не будет виновен за деяния сына.           Пусть окровавленная корона останется потерянной и забытой».', 0),
(1771, 'ruRU', 'Этот осколок времён Второй войны служит ярким напоминанием о том, насколько опасно близко Орда подошла к завоеванию горы Стальгорн.', 0),
(1827, 'ruRU', 'Малфурион, убеждённый, что Колодец Вечности был пуповиной демонов, связывающей их с физическим миром, настаивал на том, что его нужно уничтожить. Его товарищи, зная, что Колодец был источником их бессмертия и силы, были в ужасе от этой безрассудной идеи. Однако Тиранда увидела мудрость в теории Малфуриона, и убедила Кенария и их соратников штурмовать храм Азшары и найти способ навсегда закрыть Колодец.', 0),
(2063, 'ruRU', 'Культисты под началом Кел''Тузада жаждали умереть и воскреснуть на службе своему тёмному повелителю. Они восторгались перспективой бессмертия через нежизнь. По мере распространения чумы в северных землях появлялось всё больше диких зомби. Кел''Тузад взглянул на растущую армию Короля-лича и назвал её Плетью, ибо скоро она двинется к вратам Лордерона и сметёт человечество с лица мира.', 0),
(2130, 'ruRU', 'К несчастью, адмирал Праудмур погиб в бою прежде, чем Джайна смогла примириться с ним или доказать, что орки больше не кровожадные монстры. За её верность орки позволили силам Джайны безопасно вернуться домой в Тераморт.', 0),
(2150, 'ruRU', 'Трон-Ка, воин. Я не буду восхвалять твои подвиги силы и доблести. Это старые новости. Убивал ли ты людей недавно? Не много, я уверен. Ты сдаёшь позиции. Становишься мягким без вызова. Мне нужна ещё одна пара рук, и, что бы ни говорили твои подхалимы, тебе нужна тренировка, которую могу дать я. Когда до твоей тупой головы это наконец дойдёт, я буду ждать под навесом прямо у Логова. -Франг, наставник воинов', 0),
(2170, 'ruRU', 'Доргар Каменная Бровь Воин Алого Крестового похода Владыка Красных пещер Последний раз видели в горах Алтерака', 0),
(2190, 'ruRU', 'Валея Двуклинкова Воин Алого Крестового похода Гражданка Алтерака Последний раз видели глубоко в Восточных Чумных землях', 0),
(2210, 'ruRU', 'Остальные племена гурубаши разошлись каждое своей дорогой после того, как великая гражданская война оставила их земли в руинах. Племена Черепоруб, Кровавый Скальп и Тёмное Копье отправились претендовать на собственные земли в обширных джунглях Тернистой долины. Хотя над разрушенной империей установился хрупкий мир, некоторые говорили о пророчестве, что Хаккар однажды возродится в этом мире — и в тот день — он поглотит его целиком.', 0),
(2250, 'ruRU', 'Агашам,$b$bНаши агенты из Лордерона скоро встретятся с вашими делегатами. Мы уведомим вас, как только найдём подходящее место для нашего саммита.$b$bПодписано,$b$bВестник Гракус', 0),
(2270, 'ruRU', 'Нападающие... со всех сторон.$B$BВижу это в их глазах. Древобрюхи — зло. Враги.$B$BНужно защитить племя. Нужно защитить Зимний Крыл. Нужно прогнать захватчиков с нашей земли.', 0),
(2290, 'ruRU', 'Натака, всё спокойно в Тысяче Игл. Кентавры — не более чем помеха... иногда нападают, но ничего серьёзного, похожего на настоящую угрозу. Однако, похоже, есть новости об объединении кентаврийских кланов.$B$BМы всегда задумывались об угрозе объединённой безжалостной расы, такой как кентавры... Я стараюсь не задерживаться на таких мыслях, как ты знаешь... ничто не может пробить ту чистую ненависть, что они испытывают... даже друг к другу.$B$B-Длиннорог Скалоблюст', 0),
(2350, 'ruRU', 'Этот целый скелет птеродона был найден в отдалённом кратере Ун''Горо. Судя по строению скелета, ясно, что этот конкретный род ранее не встречался. Этот скелет мог сохраняться на протяжении многих веков под богатой почвой региона.', 0),
(2370, 'ruRU', '<HTML>\n<BODY>\n<IMG src="Interface\\Pictures\\14679_Tirion_256"/>\n</BODY>\n</HTML>\n', 0);
